using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;

namespace Kassyi.GSharp.Tools.SmellScan;

/// <summary>
/// Recognizes generated files the way Roslyn does: by file name (<c>.g.cs</c>, <c>.g.i.cs</c>, <c>.designer.cs</c>,
/// <c>.generated.cs</c>, <c>TemporaryGeneratedFile_*</c>) or by an <c>&lt;auto-generated&gt;</c> comment at the top of the file.
/// The <c>generated_code</c> setting of <c>.editorconfig</c> is not used: it covers all of <c>tests/**</c> here.
/// </summary>
internal static class GeneratedCodeFilter
{
    private static readonly string[] s_generatedSuffixes = [".g.cs", ".g.i.cs", ".designer.cs", ".generated.cs"];

    /// <summary>Returns true when the name of <paramref name="path"/> marks the file as generated.</summary>
    public static bool HasGeneratedName(string path)
    {
        var name = path[(path.LastIndexOf('/') + 1)..];
        if (name.StartsWith("TemporaryGeneratedFile_", StringComparison.OrdinalIgnoreCase))
        {
            return true;
        }

        foreach (var suffix in s_generatedSuffixes)
        {
            if (name.EndsWith(suffix, StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }
        }

        return false;
    }

    /// <summary>
    /// Returns true when a comment before the first token of <paramref name="root"/> contains
    /// <c>&lt;auto-generated</c> or <c>&lt;autogenerated</c>. Comments further down the file do not count.
    /// </summary>
    public static bool HasGeneratedHeader(SyntaxNode root)
    {
        foreach (var trivia in root.GetFirstToken(includeZeroWidth: true).LeadingTrivia)
        {
            if (!trivia.IsKind(SyntaxKind.SingleLineCommentTrivia) && !trivia.IsKind(SyntaxKind.MultiLineCommentTrivia))
            {
                continue;
            }

            var text = trivia.ToString();
            if (text.Contains("<auto-generated", StringComparison.OrdinalIgnoreCase)
                || text.Contains("<autogenerated", StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }
        }

        return false;
    }
}
